    // Add a full-width "Contact for Pricing" CTA inside the mobile dropdown menu (strictly hidden on desktop via .mobile-menu-cta-item)
    const navLinks = document.getElementById('links');
    if (navLinks && !navLinks.querySelector('.mobile-menu-cta-item')) {
      const li = document.createElement('li');
      li.className = 'mobile-menu-cta-item';
      li.style.listStyle = 'none';
      const a = document.createElement('a');
      a.className = 'btn btn-gold mobile-menu-cta';
      a.href = 'https://wa.me/918422037973?text=Namaste%20Rajasthan%20Readymade%20Stores%2C%20I%20would%20like%20pricing%20and%20availability.';
      a.target = '_blank';
      a.rel = 'noopener';
      a.setAttribute('data-i18n', 'nav_price');
      a.textContent = '💬 Contact for Pricing';
      a.style.justifyContent = 'center';
      a.style.borderBottom = 'none';
      li.appendChild(a);
      navLinks.appendChild(li);
    }

    // Add touch-swipe left/right support to Lightbox for mobile phones
    const lb = document.getElementById('lb');
    if (lb && !lb.dataset.swipeWired) {
      lb.dataset.swipeWired = '1';
      let touchStartX = 0;
      let touchEndX = 0;
      lb.addEventListener('touchstart', e => {
        if (e.changedTouches && e.changedTouches[0]) {
          touchStartX = e.changedTouches[0].screenX;
        }
      }, { passive: true });
      lb.addEventListener('touchend', e => {
        if (e.changedTouches && e.changedTouches[0]) {
          touchEndX = e.changedTouches[0].screenX;
          const diff = touchEndX - touchStartX;
          if (Math.abs(diff) > 45 && typeof lbStep === 'function') {
            lbStep(diff < 0 ? 1 : -1);
          }
        }
      }, { passive: true });
    }

    // Always apply the authentic Rajasthan Readymade Stores original profile logo (IMG_4840.JPEG)
    document.querySelectorAll('.logo-img').forEach(logoImg => {
      logoImg.src = RRS_LOGO_SVG;
      logoImg.addEventListener('error', () => {
        if (logoImg.src !== RRS_LOGO_SVG) {
          logoImg.src = RRS_LOGO_SVG;
        }
      });
    });
